/// <summary>
/// MPJ_22903_SalesOrderGuide
/// Responsible for publishing sales order guide into full list 
/// of items, for quick lookup during sales order entry/processing.
/// </summary>
class METSalesOrderGuidePublish
{
    // Params
    public METSalesOrderGuideID orderGuideID;

    // State
    METSalesOrderGuideTable     orderGuide;

}

Method.Source:
    /// <summary>
    /// run
    /// </summary>
    public void run()
    {
        setPrefix(strFmt("@MET:SalesOrderGuidePublishJobPrefix", orderGuideID));

        orderGuide = METSalesOrderGuideTable::findThrow(orderGuideID, true);

        ttsbegin;

        METSalesOrderGuideExpanded::deleteLines(orderGuide.SalesOrderGuideID);

        this.addInclusions();
        this.removeExclusions();

        orderGuide.ExpandedDateTime = DateTimeUtil::getSystemDateTime();
        orderGuide.Status           = METSalesOrderGuideStatus::Active;
        orderGuide.update();

        ttscommit;        

        info(strFmt("@MET:SalesOrderGuidePublishCompleted",
            orderGuide.SalesOrderGuideID,
            METSalesOrderGuideExpanded::countLines(orderGuide.SalesOrderGuideID))); 
    }

    /// <summary>
    /// Add any inclusions (item specific and attribute-based).    
    /// </summary>
    protected void addInclusions()
    {
        METSalesOrderGuideExpanded              expanded, expandedExists;
        METSalesOrderGuideLine                  orderGuideLine;
        METEcoResProductAttributeValueExpanded  productAttrValue;

        insert_recordset expanded (SalesOrderGuideID, ItemId)
        select SalesOrderGuideID, ItemId 
            from orderGuideLine
            where   orderGuideLine.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
            &&      orderGuideLine.LineType             == METSalesOrderGuideLineType::Item
            &&      orderGuideLine.IncludeExclude       == METSalesOrderGuideInclusion::Include
        notexists join expandedExists
            where   expandedExists.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
            &&      expandedExists.ItemId               == orderGuideLine.ItemId;

        insert_recordset expanded (SalesOrderGuideID, ItemId)
        select SalesOrderGuideID
            from orderGuideLine
            where   orderGuideLine.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
            &&      orderGuideLine.LineType             == METSalesOrderGuideLineType::Attribute
            &&      orderGuideLine.IncludeExclude       == METSalesOrderGuideInclusion::Include
        join ItemId from productAttrValue
            where   productAttrValue.AttributeName      == orderGuideLine.AttributeName
            &&      productAttrValue.ItemDataAreaId     == curExt()
        notexists join expandedExists
            where   expandedExists.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
            &&      expandedExists.ItemId               == productAttrValue.ItemId;                
    }

    /// <summary>
    /// Remove any exclusions (item specific and attribute-based).
    /// </summary>
    protected void removeExclusions()
    {
        METSalesOrderGuideExpanded              expanded, expandedExists;
        METSalesOrderGuideLine                  orderGuideLine;
        METEcoResProductAttributeValueExpanded  productAttrValue;

        delete_from expanded
            where   expanded.SalesOrderGuideID          == orderGuide.SalesOrderGuideID
        exists join orderGuideLine
            where   orderGuideLine.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
            &&      orderGuideLine.LineType             == METSalesOrderGuideLineType::Item
            &&      orderGuideLine.IncludeExclude       == METSalesOrderGuideInclusion::Exclude
            &&      orderGuideLine.ItemId               == expanded.ItemId;

        delete_from expanded 
            where   expanded.SalesOrderGuideID          == orderGuide.SalesOrderGuideID
        exists join orderGuideLine
            where   orderGuideLine.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
            &&      orderGuideLine.LineType             == METSalesOrderGuideLineType::Attribute
            &&      orderGuideLine.IncludeExclude       == METSalesOrderGuideInclusion::Exclude
        join productAttrValue
            where   productAttrValue.AttributeName      == orderGuideLine.AttributeName
            &&      productAttrValue.ItemDataAreaId     == curExt()
            &&      productAttrValue.ItemId             == expanded.ItemId;
        
    }

/// <summary>
/// Get/set orderGuideID
/// </summary>
/// <param name = "_orderGuideID">_orderGuideID</param>
/// <returns>orderGuideID</returns>
public METSalesOrderGuideID parmOrderGuideID(METSalesOrderGuideID _orderGuideID = orderGuideID)
{
    orderGuideID = _orderGuideID;
    return orderGuideID;
}

    /// <summary>
    /// Publish specified guide.
    /// </summary>
    /// <param name = "_orderGuide">Order guide</param>
    public static void publishGuide(METSalesOrderGuideTable _orderGuide)
    {
        METSalesOrderGuidePublish   publish      = new METSalesOrderGuidePublish();
        publish.parmOrderGuideID(_orderGuide.SalesOrderGuideID);
        publish.run();

        _orderGuide.reread();
    }

    public static void main(Args _args)
    {
        METSalesOrderGuidePublish   publish      = new METSalesOrderGuidePublish();
        METSalesOrderGuideTable     orderGuide  = _args.record();

        if(!orderGuide)
        {
            throw error(error::missingRecord(funcName()));
        }

        publish.parmOrderGuideID(orderGuide.SalesOrderGuideID);
        publish.run();

        if(FormDataUtil::getFormDataSource(orderGuide))
        {
            FormDataUtil::getFormDataSource(orderGuide).research();
        }
    }
